// OpenSky request, location, and secret-safe OAuth configuration.
// Edit only these three defaults for your location.
const defaultCenterLat = 25.7617;
const defaultCenterLon = -80.1918;
const defaultRadiusKm = 200;

function finiteNumber(value, fallback) {
    const parsed = Number(value);
    return Number.isFinite(parsed) ? parsed : fallback;
}

let cfg = {
    centerLat: defaultCenterLat,
    centerLon: defaultCenterLon,
    radiusKm: defaultRadiusKm
};

// Optional runtime overrides. The effective config is stored separately in
// flow.openskyRadarConfig so changing the defaults above still takes effect.
function applyOverride(source) {
    if (!source || typeof source !== "object") return;
    cfg.centerLat = finiteNumber(source.centerLat, cfg.centerLat);
    cfg.centerLon = finiteNumber(source.centerLon, cfg.centerLon);
    cfg.radiusKm = finiteNumber(source.radiusKm, cfg.radiusKm);
}

applyOverride(global.get("openskyRadarOverride"));
applyOverride(flow.get("openskyRadarOverride"));
applyOverride(msg.config);
applyOverride(msg);

if (cfg.centerLat < -90 || cfg.centerLat > 90) {
    node.error("centerLat must be between -90 and 90", msg);
    return null;
}
if (cfg.centerLon < -180 || cfg.centerLon > 180) {
    node.error("centerLon must be between -180 and 180", msg);
    return null;
}
if (cfg.radiusKm < 1 || cfg.radiusKm > 500) {
    node.error("radiusKm must be between 1 and 500 km", msg);
    return null;
}

const dLat = cfg.radiusKm / 111;
const safeCos = Math.max(Math.abs(Math.cos(cfg.centerLat * Math.PI / 180)), 0.05);
const dLon = cfg.radiusKm / (111 * safeCos);
const bounds = {
    lamin: Math.max(-90, cfg.centerLat - dLat),
    lamax: Math.min(90, cfg.centerLat + dLat),
    lomin: Math.max(-180, cfg.centerLon - dLon),
    lomax: Math.min(180, cfg.centerLon + dLon)
};

const areaSqDeg = (bounds.lamax - bounds.lamin) * (bounds.lomax - bounds.lomin);
const estimatedCreditCost = areaSqDeg <= 25 ? 1 : areaSqDeg <= 100 ? 2 : areaSqDeg <= 400 ? 3 : 4;

const clientId = env.get("OPENSKY_CLIENT_ID");
const clientSecret = env.get("OPENSKY_CLIENT_SECRET");
const authConfigured = Boolean(clientId && clientSecret);

cfg = Object.assign(cfg, bounds, {
    estimatedCreditCost,
    authConfigured,
    pollSeconds: 300
});
flow.set("openskyRadarConfig", cfg);

const dataUrl = "https://opensky-network.org/api/states/all" +
    "?lamin=" + bounds.lamin.toFixed(5) +
    "&lamax=" + bounds.lamax.toFixed(5) +
    "&lomin=" + bounds.lomin.toFixed(5) +
    "&lomax=" + bounds.lomax.toFixed(5) +
    "&extended=1";

msg.url = dataUrl;
msg.centerLat = cfg.centerLat;
msg.centerLon = cfg.centerLon;
msg.radiusKm = cfg.radiusKm;
msg.openskyConfig = cfg;

const mapKey = [cfg.centerLat, cfg.centerLon, cfg.radiusKm].join(":");
let mapMessage = null;
if (context.get("lastMapKey") !== mapKey) {
    context.set("lastMapKey", mapKey);
    mapMessage = { openskyConfig: cfg, _mapInit: true };
}

if (!authConfigured) {
    if ((clientId && !clientSecret) || (!clientId && clientSecret)) {
        node.warn("Both OPENSKY_CLIENT_ID and OPENSKY_CLIENT_SECRET are required; using anonymous access.");
    }
    msg._openskyAuthMode = "anonymous";
    node.status({ fill: "blue", shape: "ring", text: "anonymous • ~" + estimatedCreditCost + " credit/poll" });
    return [msg, null, mapMessage];
}

const cached = flow.get("openskyOAuth") || {};
if (cached.accessToken && cached.expiresAt > Date.now() + 60000) {
    msg.headers = { Authorization: "Bearer " + cached.accessToken };
    msg._openskyAuthMode = "authenticated";
    node.status({ fill: "green", shape: "dot", text: "authenticated • ~" + estimatedCreditCost + " credit/poll" });
    return [msg, null, mapMessage];
}

const tokenMessage = Object.assign({}, msg, {
    url: "https://auth.opensky-network.org/auth/realms/opensky-network/protocol/openid-connect/token",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    payload: "grant_type=client_credentials&client_id=" + encodeURIComponent(clientId) +
        "&client_secret=" + encodeURIComponent(clientSecret),
    _openskyDataUrl: dataUrl,
    _openskyAuthMode: "token-request"
});
node.status({ fill: "yellow", shape: "ring", text: "refreshing OAuth token" });
return [null, tokenMessage, mapMessage];

// Cache the short-lived OAuth token. Secret values never leave this path.
const status = Number(msg.statusCode || 0);
const data = msg.payload && typeof msg.payload === "object" ? msg.payload : {};

if (status >= 200 && status < 300 && data.access_token) {
    const expiresIn = Number(data.expires_in) || 1800;
    flow.set("openskyOAuth", {
        accessToken: data.access_token,
        expiresAt: Date.now() + Math.max(60, expiresIn - 30) * 1000
    });

    msg.url = msg._openskyDataUrl;
    msg.headers = { Authorization: "Bearer " + data.access_token };
    msg.payload = "";
    msg._openskyAuthMode = "authenticated";
    delete msg.statusCode;
    delete msg._openskyDataUrl;
    node.status({ fill: "green", shape: "dot", text: "OAuth token ready" });
    return [msg, null, null];
}

// Do not expose the token-request body in Debug. Fall back to anonymous data
// so a bad optional credential does not break the public demo.
flow.set("openskyOAuth", null);
const reason = status ? "OAuth request returned HTTP " + status : "OAuth token response was invalid";
node.warn(reason + "; falling back to anonymous access.");

const fallback = {
    url: msg._openskyDataUrl,
    centerLat: msg.centerLat,
    centerLon: msg.centerLon,
    radiusKm: msg.radiusKm,
    openskyConfig: msg.openskyConfig,
    _openskyAuthMode: "anonymous fallback"
};
const mapError = {
    payload: {
        command: {
            showdialog: "<b>OpenSky sign-in failed</b><br>Using anonymous access for this update. Check the two OPENSKY environment variables."
        }
    }
};
const safeError = { payload: { source: "OpenSky OAuth", statusCode: status || null, message: reason } };
return [fallback, mapError, safeError];

// Validate the response and turn state vectors into polished map markers.
function escapeHtml(value) {
    return String(value == null ? "" : value)
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#39;");
}

function getHeader(headers, name) {
    if (!headers || typeof headers !== "object") return "";
    const wanted = name.toLowerCase();
    const key = Object.keys(headers).find(k => k.toLowerCase() === wanted);
    return key ? headers[key] : "";
}

function getDistanceAndBearing(lat1, lon1, lat2, lon2) {
    const toRad = d => d * Math.PI / 180;
    const dLat = toRad(lat2 - lat1);
    const dLon = toRad(lon2 - lon1);
    const phi1 = toRad(lat1);
    const phi2 = toRad(lat2);
    const a = Math.sin(dLat / 2) ** 2 + Math.cos(phi1) * Math.cos(phi2) * Math.sin(dLon / 2) ** 2;
    const distanceKm = 6371 * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
    const y = Math.sin(dLon) * Math.cos(phi2);
    const x = Math.cos(phi1) * Math.sin(phi2) - Math.sin(phi1) * Math.cos(phi2) * Math.cos(dLon);
    const bearingDeg = (Math.atan2(y, x) * 180 / Math.PI + 360) % 360;
    const directions = ["N", "NE", "E", "SE", "S", "SW", "W", "NW"];
    return { distanceKm, bearingDeg, bearingCompass: directions[Math.round(bearingDeg / 45) % 8] };
}

const airlineConfig = {
    AAL: ["American Airlines", "#ef4444"],
    ACA: ["Air Canada", "#dc2626"],
    AFR: ["Air France", "#2563eb"],
    ANA: ["All Nippon Airways", "#2563eb"],
    AVA: ["Avianca", "#ef4444"],
    BAW: ["British Airways", "#2563eb"],
    CMP: ["Copa Airlines", "#0f766e"],
    DAL: ["Delta Air Lines", "#2563eb"],
    DLH: ["Lufthansa", "#facc15"],
    FFT: ["Frontier Airlines", "#16a34a"],
    JAL: ["Japan Airlines", "#dc2626"],
    JBU: ["JetBlue Airways", "#0284c7"],
    KLM: ["KLM", "#0ea5e9"],
    LAT: ["LATAM Airlines", "#7c3aed"],
    NKS: ["Spirit Airlines", "#facc15"],
    ROU: ["Air Canada Rouge", "#e11d48"],
    RYR: ["Ryanair", "#1d4ed8"],
    SWA: ["Southwest Airlines", "#3b82f6"],
    UAE: ["Emirates", "#dc2626"],
    UAL: ["United Airlines", "#2563eb"],
    VJA: ["Vista America", "#be123c"],
    VJS: ["VistaJet", "#be123c"]
};

function airlineInfo(raw) {
    const callsign = String(raw || "").trim().toUpperCase();
    const match = callsign.match(/^[A-Z]{3}/);
    const prefix = match ? match[0] : "";
    if (airlineConfig[prefix]) {
        return { callsign, name: airlineConfig[prefix][0], color: airlineConfig[prefix][1] };
    }
    let hash = 0;
    for (let i = 0; i < prefix.length; i++) hash = ((hash << 5) - hash + prefix.charCodeAt(i)) | 0;
    return { callsign, name: "", color: prefix ? "hsl(" + (Math.abs(hash) % 360) + ",72%,48%)" : "#64748b" };
}

const categoryNames = [
    "Unspecified", "No emitter category", "Light", "Small", "Large", "High-vortex large",
    "Heavy", "High performance", "Rotorcraft", "Glider", "Lighter-than-air", "Skydiver",
    "Ultralight", "Reserved", "UAV", "Space vehicle", "Emergency vehicle", "Service vehicle",
    "Point obstacle", "Cluster obstacle", "Line obstacle"
];

function classify(meta, category) {
    const text = ((meta && meta.model) || "") + " " + ((meta && meta.category_description) || "");
    if (/helicopter/i.test(text) || category === 8) return "helicopter";
    if (/glider/i.test(text) || category === 9) return "glider";
    if (/balloon/i.test(text) || category === 10) return "balloon";
    if (category === 14) return "uav";
    return "airplane";
}

function errorOutputs(title, detail, statusCode) {
    const safeTitle = escapeHtml(title);
    const safeDetail = escapeHtml(detail);
    const ui = {
        payload: {
            command: {
                toptitle: "OpenSky Radar • attention needed",
                showdialog: "<div style='font-family:system-ui;min-width:260px'><b>" + safeTitle + "</b><br>" + safeDetail + "</div>"
            }
        }
    };
    const debug = { payload: { source: "OpenSky states", statusCode: statusCode || null, message: detail } };
    return [null, ui, debug];
}

const statusCode = Number(msg.statusCode || (msg.payload && Array.isArray(msg.payload.states) ? 200 : 0));
if (statusCode < 200 || statusCode >= 300) {
    if (statusCode === 401) {
        flow.set("openskyOAuth", null);
        return errorOutputs("OpenSky authorization expired", "The token was cleared and will refresh on the next poll.", statusCode);
    }
    if (statusCode === 429) {
        const retry = getHeader(msg.headers, "x-rate-limit-retry-after-seconds");
        return errorOutputs("OpenSky rate limit reached", retry ? "Try again in " + retry + " seconds." : "Wait for the API credit bucket to refill.", statusCode);
    }
    return errorOutputs("OpenSky request failed", "HTTP " + (statusCode || "unknown") + ". Check Node-RED's Debug sidebar.", statusCode);
}

if (!msg.payload || !Array.isArray(msg.payload.states)) {
    return errorOutputs("Unexpected OpenSky response", "The response did not contain a states array.", statusCode);
}

const cfg = msg.openskyConfig || flow.get("openskyRadarConfig") || {};
const centerLat = Number.isFinite(Number(msg.centerLat)) ? Number(msg.centerLat) : Number(cfg.centerLat);
const centerLon = Number.isFinite(Number(msg.centerLon)) ? Number(msg.centerLon) : Number(cfg.centerLon);
const radiusKm = Number.isFinite(Number(msg.radiusKm)) ? Number(msg.radiusKm) : Number(cfg.radiusKm || 200);
const aircraftDb = global.get("aircraftDb") || {};
const markers = [];
let airborne = 0;
let grounded = 0;
const now = Date.now();

msg.payload.states.forEach(row => {
    if (!Array.isArray(row) || row.length < 17) return;
    const icao24 = String(row[0] || "").toLowerCase();
    const lon = Number(row[5]);
    const lat = Number(row[6]);
    if (!icao24 || !Number.isFinite(lat) || !Number.isFinite(lon)) return;

    const distance = getDistanceAndBearing(centerLat, centerLon, lat, lon);
    if (distance.distanceKm > radiusKm) return; // Trim the bounding-box corners to the requested circle.

    const category = Number.isInteger(row[17]) ? row[17] : null;
    if (category != null && category >= 16) return; // Hide service vehicles and obstacles.
    const onGround = Boolean(row[8]);
    const trueTrack = Number(row[10]);
    const velocityMs = row[9] == null ? null : Number(row[9]);
    const altitudeM = row[13] != null ? Number(row[13]) : (row[7] != null ? Number(row[7]) : null);
    const altitudeFt = Number.isFinite(altitudeM) ? Math.max(0, Math.round(altitudeM * 3.28084 / 100) * 100) : null;
    const speedKts = Number.isFinite(velocityMs) ? Math.max(0, Math.round(velocityMs * 1.94384)) : null;
    const lastContact = Number(row[4]);
    const ageSec = Number.isFinite(lastContact) ? Math.max(0, Math.round((now - lastContact * 1000) / 1000)) : null;
    const airline = airlineInfo(row[1]);
    const displayFlight = airline.callsign || icao24.toUpperCase();
    const meta = aircraftDb[icao24] || {};
    const aircraftLabel = meta.model || meta.typecode || "";
    const vehicleClass = classify(meta, category);
    const icon = vehicleClass === "helicopter" ? "helicopter" : vehicleClass === "uav" ? "uav" : vehicleClass === "glider" ? "smallplane" : "plane";
    const layer = onGround ? "On ground" : vehicleClass === "helicopter" ? "Rotorcraft" : "Airborne aircraft";
    const categoryLabel = category != null && categoryNames[category] ? categoryNames[category] : "Unspecified";

    if (onGround) grounded++; else airborne++;

    const statusColor = onGround ? "#f59e0b" : "#22c55e";
    const rows = [
        ["Operator", airline.name || "Not identified"],
        ["Altitude", altitudeFt == null ? "Not available" : altitudeFt.toLocaleString("en-US") + " ft"],
        ["Ground speed", speedKts == null ? "Not available" : speedKts + " kt"],
        ["From center", distance.distanceKm.toFixed(1) + " km " + distance.bearingCompass + " (" + distance.bearingDeg.toFixed(0) + "°)"],
        ["Aircraft", aircraftLabel || categoryLabel],
        ["Country", row[2] || "Not available"],
        ["Last contact", ageSec == null ? "Not available" : ageSec + "s ago"]
    ];
    const detailRows = rows.map(item =>
        "<div style='display:grid;grid-template-columns:92px 1fr;gap:8px;padding:5px 0;border-top:1px solid #e2e8f0'>" +
        "<span style='color:#64748b'>" + escapeHtml(item[0]) + "</span><b style='color:#0f172a'>" + escapeHtml(item[1]) + "</b></div>"
    ).join("");
    const popup = "<div style='font:13px/1.35 system-ui,-apple-system,sans-serif;min-width:255px'>" +
        "<div style='display:flex;justify-content:space-between;align-items:center;gap:12px;padding-bottom:9px'>" +
        "<div><div style='font-size:18px;font-weight:800;color:#0f172a'>" + escapeHtml(displayFlight) + "</div>" +
        "<div style='color:#64748b;text-transform:uppercase;letter-spacing:.08em;font-size:10px'>ICAO " + escapeHtml(icao24) + "</div></div>" +
        "<span style='background:" + statusColor + ";color:white;border-radius:999px;padding:4px 8px;font-size:10px;font-weight:800'>" + (onGround ? "ON GROUND" : "AIRBORNE") + "</span></div>" +
        detailRows + "</div>";

    markers.push({
        name: displayFlight + " · " + icao24,
        lat,
        lon,
        layer,
        icon,
        iconColor: airline.color,
        iconSize: 26,
        bearing: Number.isFinite(trueTrack) ? trueTrack : 0,
        ttl: Math.max(90, Number(cfg.pollSeconds || 300) + 120),
        tooltip: displayFlight + (altitudeFt == null ? "" : " • " + altitudeFt.toLocaleString("en-US") + " ft"),
        popup,
        contextmenu: ""
    });
});

const responseTime = Number(msg.payload.time);
const updated = Number.isFinite(responseTime) ? new Date(responseTime * 1000) : new Date();
const updatedLabel = updated.toISOString().slice(11, 19) + " UTC";
const remaining = getHeader(msg.headers, "x-rate-limit-remaining");
const authLabel = msg._openskyAuthMode === "authenticated" ? "Authenticated" : "Anonymous";
const legend = "<div style='font:12px/1.4 system-ui;min-width:190px'>" +
    "<b style='font-size:13px'>Live radar status</b><br>" +
    "<span style='color:#22c55e'>●</span> " + airborne + " airborne &nbsp; " +
    "<span style='color:#f59e0b'>●</span> " + grounded + " on ground<br>" +
    "Updated " + updatedLabel + " • " + authLabel +
    (remaining !== "" ? "<br>API credits remaining: " + escapeHtml(remaining) : "") + "</div>";

const title = "OpenSky Live Air Traffic • " + markers.length + " aircraft";
flow.set("openskyRadarStatus", { title, legend, updatedAt: updated.toISOString() });
// A Function output can emit an array of messages. The worldmap node expects
// one marker object per message, not an array inside a single msg.payload.
const markerMessages = markers.map(marker => ({ payload: marker }));
const uiMessage = {
    payload: {
        command: {
            toptitle: title,
            legend,
            showdialog: ""
        }
    }
};
node.status({ fill: "green", shape: "dot", text: markers.length + " aircraft • " + updatedLabel });
return [markerMessages, uiMessage, null];

// Rebuild the static map UI whenever a browser connects or config changes.
const cfg = msg.openskyConfig || flow.get("openskyRadarConfig") || {
    centerLat: 25.7617,
    centerLon: -80.1918,
    radiusKm: 200
};
const radarStatus = flow.get("openskyRadarStatus") || {};
const dLat = Number(cfg.radiusKm) / 111;
const safeCos = Math.max(Math.abs(Math.cos(Number(cfg.centerLat) * Math.PI / 180)), 0.05);
const dLon = Number(cfg.radiusKm) / (111 * safeCos);

const commandMessage = {
    _sessionid: msg._sessionid,
    payload: {
        command: {
            bounds: [
                [Math.max(-90, Number(cfg.centerLat) - dLat), Math.max(-180, Number(cfg.centerLon) - dLon)],
                [Math.min(90, Number(cfg.centerLat) + dLat), Math.min(180, Number(cfg.centerLon) + dLon)]
            ],
            toptitle: radarStatus.title || "OpenSky Live Air Traffic",
            legend: radarStatus.legend || "<div style='font:12px/1.4 system-ui'><b>Live radar status</b><br>Waiting for the first OpenSky update…</div>",
            hiderightclick: true,
            contextmenu: "",
            sidcEdgeIcon: false
        }
    }
};
const rangeMessage = {
    _sessionid: msg._sessionid,
    payload: {
        name: "Radar range",
        lat: Number(cfg.centerLat),
        lon: Number(cfg.centerLon),
        radius: Number(cfg.radiusKm) * 1000,
        layer: "Radar coverage",
        color: "#38bdf8",
        fillColor: "#38bdf8",
        fillOpacity: 0.04,
        opacity: 0.7,
        weight: 2,
        dashArray: "8 8",
        ttl: 0,
        clickable: true,
        popup: "<b>Radar coverage</b><br>" + Number(cfg.radiusKm).toFixed(0) + " km from the selected center.",
        contextmenu: ""
    }
};
const centerMessage = {
    _sessionid: msg._sessionid,
    payload: {
        name: "Radar Center",
        lat: Number(cfg.centerLat),
        lon: Number(cfg.centerLon),
        layer: "Radar coverage",
        icon: "home",
        iconColor: "#38bdf8",
        iconSize: 28,
        ttl: 0,
        tooltip: "Radar Center • " + Number(cfg.radiusKm).toFixed(0) + " km range",
        popup: "<b>Radar Center</b><br>Latitude: " + Number(cfg.centerLat).toFixed(4) +
            "<br>Longitude: " + Number(cfg.centerLon).toFixed(4) +
            "<br>Search radius: " + Number(cfg.radiusKm).toFixed(0) + " km",
        contextmenu: ""
    }
};
return [commandMessage, rangeMessage, centerMessage];

// Convert transport failures into a visible map message and a safe Debug entry.
const detail = msg.error && msg.error.message ? msg.error.message : "The HTTP request could not be completed.";
const ui = {
    payload: {
        command: {
            toptitle: "OpenSky Radar • connection problem",
            showdialog: "<div style='font-family:system-ui;min-width:260px'><b>OpenSky connection problem</b><br>Check internet/DNS access from the Node-RED host. Existing aircraft remain visible during the refresh grace period.</div>"
        }
    }
};
const debug = { payload: { source: "OpenSky HTTP", message: detail } };
node.status({ fill: "red", shape: "ring", text: "OpenSky connection failed" });
return [ui, debug];
